import os
import time
import boto3
from botocore.exceptions import ClientError

def poll_transcription(payload, config=None):
    config = config or {}
    transcribe_client = boto3.client('transcribe',
        aws_access_key_id=config.get('aws_access_key_id', os.environ.get('AWS_ACCESS_KEY_ID')),
        aws_secret_access_key=config.get('aws_secret_access_key', os.environ.get('AWS_SECRET_ACCESS_KEY')),
        region_name=config.get('region_name', 'us-east-1')
    )
    job_name = payload.get('job_name')
    if not job_name:
        raise ValueError("Job name must be provided in payload")

    while True:
        try:
            response = transcribe_client.get_transcription_job(TranscriptionJobName=job_name)
            status = response['TranscriptionJob']['TranscriptionJobStatus']
            if status == 'COMPLETED':
                transcript_uri = response['TranscriptionJob']['Transcript']['TranscriptFileUri']
                import json
                import urllib.request
                with urllib.request.urlopen(transcript_uri) as url:
                    transcript_data = json.loads(url.read().decode())
                result = transcript_data['results']['transcripts'][0]['transcript']
                return result
            elif status == 'FAILED':
                failure_reason = response['TranscriptionJob'].get('FailureReason', 'Unknown failure')
                raise RuntimeError(f"Transcription job failed: {failure_reason}")
            else:
                time.sleep(5)
        except ClientError as e:
            raise RuntimeError(f"AWS Transcribe error: {e}")
